import { describe, it, expect } from "vitest";
import {
  buildCatalogOptions,
  curateClass,
  searchCatalog,
  searchCuratedClasses,
} from "../src/curatedClasses";
import { curatedClasses } from "../src/data";

describe("buildCatalogOptions (the curation picker)", () => {
  it("uses the class's current course number for a renumbered course (INTEGBI 32 -> 130)", () => {
    const options = buildCatalogOptions();
    const integbi = options.find((o) => o.classId === "cls-1");
    expect(integbi?.subject).toBe("INTEGBI");
    expect(integbi?.courseNumber).toBe("130");
  });

  it("uses the class's current course number for a renumbered course (COLWRIT 6A -> 22B)", () => {
    const options = buildCatalogOptions();
    const colwrit = options.find((o) => o.classId === "cls-2");
    expect(colwrit?.subject).toBe("COLWRIT");
    expect(colwrit?.courseNumber).toBe("22B");
  });

  it("still works for a course that was never renumbered (control case)", () => {
    const options = buildCatalogOptions();
    const math = options.find((o) => o.classId === "cls-3");
    expect(math?.subject).toBe("MATH");
    expect(math?.courseNumber).toBe("1A");
  });
});

describe("curateClass (saving a picker selection)", () => {
  it("saves the class's real subject/number, not the stale course's", () => {
    const options = buildCatalogOptions();
    const integbi = options.find((o) => o.classId === "cls-1")!;
    const curated = curateClass(integbi, "A great class");
    expect(curated.subject).toBe("INTEGBI");
    expect(curated.courseNumber).toBe("130");
  });
});

describe("searchCatalog (picker search)", () => {
  it("finds a renumbered class by its real, current number", () => {
    const options = buildCatalogOptions();
    const results = searchCatalog("INTEGBI 130", options);
    expect(results.map((r) => r.classId)).toContain("cls-1");
  });

  it("does not still respond to the class's old, superseded number", () => {
    const options = buildCatalogOptions();
    const results = searchCatalog("INTEGBI 32", options);
    expect(results.map((r) => r.classId)).not.toContain("cls-1");
  });
});

describe("searchCuratedClasses (the curated-classes list page)", () => {
  it("finds a curated class by its course number, not its section number", () => {
    // cur-1 is INTEGBI 130, section 001. Searching "130" (the course
    // number) must find it; the list page's index must not be built
    // from the section number instead.
    const results = searchCuratedClasses("INTEGBI 130", curatedClasses);
    expect(results.map((r) => r._id)).toContain("cur-1");
  });

  it("does not match on the section number as if it were the course number", () => {
    // Searching for the section number "001" alone shouldn't be treated
    // as if someone searched for course number "001" -- it happens not
    // to collide with any real course number in this fixture set, but a
    // correct index still keys off courseNumber, not sectionNumber.
    const results = searchCuratedClasses("MATH 1A", curatedClasses);
    expect(results.map((r) => r._id)).toContain("cur-2");
  });
});
